-- Executable proposed schema (contract, not the final Rust migration). One database per project
-- (.hoh/state.db), therefore events.seq is the per-project sequence and UNIQUE keys are per project.
-- Connection settings are not schema: the writer opens with journal_mode=WAL, foreign_keys=ON and a
-- bounded busy_timeout (see REQ-062). Evolution: new numbered migration + user_version bump +
-- round-trip/rollback tests; an older binary must refuse a database whose user_version is higher.
PRAGMA foreign_keys = ON;
BEGIN;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE projects(project_id TEXT PRIMARY KEY, repo_path TEXT NOT NULL UNIQUE, host_epoch INTEGER NOT NULL DEFAULT 0 CHECK(host_epoch>=0), created_at TEXT NOT NULL);
CREATE TABLE specs(spec_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(project_id), sha256 TEXT NOT NULL CHECK(length(sha256)=64), revision INTEGER NOT NULL CHECK(revision>0), UNIQUE(project_id,revision));
CREATE TABLE change_requests(cr_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(project_id), base_spec_id TEXT NOT NULL REFERENCES specs(spec_id), result_spec_id TEXT REFERENCES specs(spec_id), state TEXT NOT NULL CHECK(state IN ('PROPOSED','APPROVED','REJECTED','APPLIED')), reason TEXT NOT NULL, impact_json TEXT NOT NULL CHECK(json_valid(impact_json)), decided_by TEXT, created_at TEXT NOT NULL);
-- spec_id is NULL until SPECIFYING produces the first spec revision (CR-003). blocked_reason is the highest-precedence entry of blocked_reasons_json.
CREATE TABLE runs(run_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(project_id), spec_id TEXT REFERENCES specs(spec_id), state TEXT NOT NULL CHECK(state IN ('CREATED','DISCOVERING','SPECIFYING','READY','RUNNING','VERIFYING','PAUSE_REQUESTED','PAUSED','WAITING_EXTERNAL','BLOCKED','CANCEL_REQUESTED','CANCELLED','INCOMPLETE','FAILED','COMPLETED')), mode TEXT NOT NULL CHECK(mode IN ('PLAN','BUILD','AUTO')), revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0), config_revision INTEGER NOT NULL DEFAULT 0, resume_state TEXT, blocked_reason TEXT, blocked_reasons_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(blocked_reasons_json)), config_snapshot_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(config_snapshot_json)), deadline_at TEXT, created_at TEXT NOT NULL, CHECK(state<>'BLOCKED' OR blocked_reason IS NOT NULL));
-- Role epoch is per (run, role): rebinding the Commander must not fence the Developer's in-flight work.
CREATE TABLE role_bindings(run_id TEXT NOT NULL REFERENCES runs(run_id), role TEXT NOT NULL, agent TEXT NOT NULL CHECK(agent IN ('codex','claude','pi')), model TEXT, session_id TEXT REFERENCES sessions(session_id), role_epoch INTEGER NOT NULL CHECK(role_epoch>0), config_revision INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(state IN ('ACTIVE','BLOCKED')), blocked_reason TEXT, missing_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(missing_json)), bound_at TEXT NOT NULL, PRIMARY KEY(run_id,role), CHECK(state<>'BLOCKED' OR blocked_reason IS NOT NULL));
-- Project team configuration history; ConfigureTeam's expected_revision is the latest APPLIED revision (CR-003).
CREATE TABLE team_revisions(project_id TEXT NOT NULL REFERENCES projects(project_id), revision INTEGER NOT NULL CHECK(revision>=0), config_json TEXT NOT NULL CHECK(json_valid(config_json)), state TEXT NOT NULL CHECK(state IN ('PENDING','APPLIED','REJECTED')), command_id TEXT REFERENCES commands(command_id), created_at TEXT NOT NULL, applied_at TEXT, PRIMARY KEY(project_id,revision));
CREATE TABLE requirements(requirement_id TEXT NOT NULL, spec_id TEXT NOT NULL REFERENCES specs(spec_id), title TEXT NOT NULL, required_release INTEGER NOT NULL CHECK(required_release IN (0,1)), release_class TEXT NOT NULL DEFAULT 'required' CHECK(release_class IN ('required','degradable')), PRIMARY KEY(requirement_id,spec_id));
CREATE TABLE acceptance_criteria(ac_id TEXT NOT NULL, requirement_id TEXT NOT NULL, spec_id TEXT NOT NULL, body TEXT NOT NULL, check_id TEXT NOT NULL, PRIMARY KEY(ac_id,spec_id), FOREIGN KEY(requirement_id,spec_id) REFERENCES requirements(requirement_id,spec_id));
CREATE TABLE iterations(iteration_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),number INTEGER NOT NULL CHECK(number>0), UNIQUE(run_id,number));
CREATE TABLE tasks(task_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), iteration_id TEXT REFERENCES iterations(iteration_id), spec_id TEXT NOT NULL REFERENCES specs(spec_id), state TEXT NOT NULL CHECK(state IN ('PENDING','READY','LEASED','RUNNING','IMPLEMENTED','VERIFYING','ACCEPTED','BLOCKED','CANCELLED')), revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0), role TEXT NOT NULL, writer INTEGER NOT NULL DEFAULT 0 CHECK(writer IN (0,1)), created_seq INTEGER NOT NULL, user_value INTEGER NOT NULL DEFAULT 0 CHECK(user_value BETWEEN 0 AND 5), unblock_value INTEGER NOT NULL DEFAULT 0 CHECK(unblock_value BETWEEN 0 AND 5), risk_reduction INTEGER NOT NULL DEFAULT 0 CHECK(risk_reduction BETWEEN 0 AND 5), information_gain INTEGER NOT NULL DEFAULT 0 CHECK(information_gain BETWEEN 0 AND 5), cost_estimate INTEGER NOT NULL DEFAULT 3 CHECK(cost_estimate BETWEEN 1 AND 5), layer INTEGER NOT NULL DEFAULT 2 CHECK(layer IN (0,1,2)), wait_rounds INTEGER NOT NULL DEFAULT 0 CHECK(wait_rounds>=0), first_eligible_seq INTEGER, attempt_count INTEGER NOT NULL DEFAULT 0 CHECK(attempt_count>=0), next_retry_at TEXT, blocked_reason TEXT);
CREATE TABLE task_dependencies(task_id TEXT NOT NULL REFERENCES tasks(task_id),depends_on TEXT NOT NULL REFERENCES tasks(task_id),PRIMARY KEY(task_id,depends_on),CHECK(task_id<>depends_on));
CREATE TABLE task_requirements(task_id TEXT NOT NULL REFERENCES tasks(task_id), requirement_id TEXT NOT NULL,spec_id TEXT NOT NULL,PRIMARY KEY(task_id,requirement_id,spec_id),FOREIGN KEY(requirement_id,spec_id) REFERENCES requirements(requirement_id,spec_id));
CREATE TABLE sessions(session_id TEXT PRIMARY KEY,agent TEXT NOT NULL,role TEXT NOT NULL,native_id TEXT,native_path TEXT,agent_version TEXT NOT NULL,capabilities_json TEXT NOT NULL CHECK(json_valid(capabilities_json)));
CREATE TABLE prompt_revisions(revision_id TEXT PRIMARY KEY, layer TEXT NOT NULL CHECK(layer IN ('builtin','global','project','run')), role TEXT NOT NULL, parent_revision TEXT REFERENCES prompt_revisions(revision_id), content_sha256 TEXT NOT NULL CHECK(length(content_sha256)=64), path TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE attempts(attempt_id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(task_id),session_id TEXT REFERENCES sessions(session_id),state TEXT NOT NULL CHECK(state IN ('PREPARED','STARTING','RUNNING','SETTLED','FAILED','CANCELLED','UNKNOWN_EFFECT')), role_epoch INTEGER NOT NULL,host_epoch INTEGER NOT NULL,config_revision INTEGER NOT NULL,prompt_revision TEXT REFERENCES prompt_revisions(revision_id),prompt_sha256 TEXT CHECK(prompt_sha256 IS NULL OR length(prompt_sha256)=64),resource_bundle_version TEXT,boot_id TEXT,pid INTEGER,process_start_id TEXT,started_at TEXT,ended_at TEXT,raw_log_path TEXT,agent TEXT CHECK(agent IS NULL OR agent IN ('codex','claude','pi')),resolved_model TEXT,failure_reason TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancel_requested IN (0,1)),usage_json TEXT CHECK(usage_json IS NULL OR json_valid(usage_json)),cost_usd REAL CHECK(cost_usd IS NULL OR cost_usd>=0),UNIQUE(task_id,attempt_id));
CREATE TABLE leases(project_id TEXT NOT NULL REFERENCES projects(project_id),kind TEXT NOT NULL CHECK(kind IN ('writer','supervisor') OR kind GLOB 'reader-[1-9]*'),attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),epoch INTEGER NOT NULL CHECK(epoch>0),expires_at TEXT NOT NULL,PRIMARY KEY(project_id,kind));
CREATE TABLE budgets(scope_kind TEXT NOT NULL CHECK(scope_kind IN ('run','task','role')), scope_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('wall_seconds','iterations','attempts','tokens','usd')), limit_value REAL, used_value REAL NOT NULL DEFAULT 0 CHECK(used_value>=0), reserved_value REAL NOT NULL DEFAULT 0 CHECK(reserved_value>=0), price_known INTEGER NOT NULL DEFAULT 1 CHECK(price_known IN (0,1)), PRIMARY KEY(scope_kind,scope_id,kind));
CREATE TABLE candidates(candidate_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),git_commit TEXT NOT NULL CHECK(length(git_commit) IN (40,64)),git_tree TEXT NOT NULL CHECK(length(git_tree) IN (40,64)),spec_sha256 TEXT NOT NULL CHECK(length(spec_sha256)=64),environment_sha256 TEXT NOT NULL CHECK(length(environment_sha256)=64),test_plan_sha256 TEXT NOT NULL CHECK(length(test_plan_sha256)=64),source_path TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'FROZEN' CHECK(state IN ('FROZEN','VERIFYING','ACCEPTED','REJECTED','STALE','INVALID')),created_at TEXT NOT NULL);
CREATE TABLE artifacts(artifact_id TEXT PRIMARY KEY,sha256 TEXT NOT NULL CHECK(length(sha256)=64),path TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>=0),mime TEXT NOT NULL,UNIQUE(sha256,path));
CREATE TABLE evidence(evidence_id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL REFERENCES candidates(candidate_id),attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),check_id TEXT NOT NULL,kind TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('PASS','DEGRADED','FAIL','BLOCKED','SKIPPED','INVALID','UNKNOWN','FLAKY','NOT_RUN')),mode TEXT NOT NULL CHECK(mode IN ('mock','live','product')),created_at TEXT NOT NULL);
CREATE TABLE acceptance_results(ac_id TEXT NOT NULL,spec_id TEXT NOT NULL,candidate_id TEXT NOT NULL REFERENCES candidates(candidate_id),evidence_id TEXT NOT NULL REFERENCES evidence(evidence_id),status TEXT NOT NULL CHECK(status IN ('PASS','DEGRADED','FAIL','BLOCKED','FLAKY','NOT_RUN','INVALID','UNKNOWN','STALE')),reason TEXT,PRIMARY KEY(ac_id,spec_id,candidate_id,evidence_id),FOREIGN KEY(ac_id,spec_id) REFERENCES acceptance_criteria(ac_id,spec_id));
CREATE TABLE issues(issue_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),candidate_id TEXT REFERENCES candidates(candidate_id),fingerprint TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('critical','high','medium','low')),state TEXT NOT NULL CHECK(state IN ('OPEN','RESOLVED','REOPENED')),description TEXT NOT NULL,report_id TEXT REFERENCES independent_reports(report_id),finding_id TEXT,CHECK(finding_id IS NULL OR report_id IS NOT NULL));
-- QA/Review reports bound to candidate, spec, session, raw session and native attempt (REQ-053/054, CR-003). STALE once a newer candidate exists.
CREATE TABLE independent_reports(report_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),candidate_id TEXT NOT NULL REFERENCES candidates(candidate_id),role TEXT NOT NULL CHECK(role IN ('qa','reviewer')),session_id TEXT NOT NULL REFERENCES sessions(session_id),spec_sha256 TEXT NOT NULL CHECK(length(spec_sha256)=64),status TEXT NOT NULL CHECK(status IN ('PASS','FAIL','UNKNOWN')),state TEXT NOT NULL CHECK(state IN ('CURRENT','STALE','REJECTED')),reject_reason TEXT,attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),report_artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),raw_session_artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),created_at TEXT NOT NULL,CHECK(state<>'REJECTED' OR reject_reason IS NOT NULL));
CREATE TABLE releases(release_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),candidate_id TEXT NOT NULL REFERENCES candidates(candidate_id),profile TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('COMPLETED','COMPLETED_DEGRADED','INTERIM_RELEASED','INCOMPLETE','BLOCKED','FAILED')),manifest_sha256 TEXT NOT NULL CHECK(length(manifest_sha256)=64),created_at TEXT NOT NULL);
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(project_id),event_id TEXT NOT NULL UNIQUE,run_id TEXT REFERENCES runs(run_id),kind TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),created_at TEXT NOT NULL);
-- result_json holds the exact 202 body; a replay returns it byte for byte (CR-003).
CREATE TABLE commands(command_id TEXT PRIMARY KEY,run_id TEXT REFERENCES runs(run_id),idempotency_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN ('StartRun','SetMode','SendInput','ConfigureTeam','ProposeSpecChange','PauseRun','ResumeRun','CancelRun','ApproveSpec','AnswerQuestion')),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),payload_sha256 TEXT NOT NULL CHECK(length(payload_sha256)=64),expected_revision INTEGER NOT NULL,result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)),accepted_at TEXT NOT NULL);
CREATE TABLE outbox(message_id TEXT PRIMARY KEY,event_seq INTEGER NOT NULL REFERENCES events(seq),run_id TEXT REFERENCES runs(run_id),recipient_role TEXT NOT NULL,role_epoch INTEGER NOT NULL DEFAULT 1,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),state TEXT NOT NULL CHECK(state IN ('PENDING','DELIVERING','ACKED','DEAD_LETTER')),attempt_count INTEGER NOT NULL DEFAULT 0 CHECK(attempt_count>=0),next_retry_at TEXT,last_error TEXT);
CREATE TABLE receipts(consumer TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES outbox(message_id),applied_at TEXT NOT NULL,result_json TEXT NOT NULL CHECK(json_valid(result_json)),PRIMARY KEY(consumer,message_id));
CREATE TABLE handoffs(handoff_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),from_role TEXT NOT NULL,to_role TEXT NOT NULL,role_epoch INTEGER NOT NULL CHECK(role_epoch>0),package_artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),state TEXT NOT NULL CHECK(state IN ('PREPARED','DELIVERED','ACCEPTED','REJECTED')),created_at TEXT NOT NULL);
CREATE TABLE effects(effect_key TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),state TEXT NOT NULL CHECK(state IN ('PREPARED','STARTED','OBSERVED','COMMITTED','UNKNOWN')),external_ref TEXT,artifact_sha256 TEXT);
CREATE TABLE decisions(decision_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),role_epoch INTEGER NOT NULL,expected_revision INTEGER NOT NULL,reason_code TEXT,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),state TEXT NOT NULL CHECK(state IN ('PROPOSED','APPLIED','REJECTED')));
-- Supervisor wake-ups: one row per trigger; at most one PENDING trigger per dedup key (run, fingerprint, spec revision), later events of
-- the same key join it (event_seqs_json); last_handled_seq survives restarts (CR-003).
CREATE TABLE supervisor_triggers(trigger_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),fingerprint TEXT NOT NULL,spec_id TEXT REFERENCES specs(spec_id),severity TEXT NOT NULL CHECK(severity IN ('integrity','critical','high','normal')),event_seqs_json TEXT NOT NULL CHECK(json_valid(event_seqs_json) AND json_array_length(event_seqs_json)>0),first_seq INTEGER NOT NULL,last_seq INTEGER NOT NULL CHECK(last_seq>=first_seq),due_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('PENDING','HANDLED','SUPERSEDED')),created_at TEXT NOT NULL);
CREATE TABLE supervisor_cursor(run_id TEXT PRIMARY KEY REFERENCES runs(run_id),last_handled_seq INTEGER NOT NULL DEFAULT 0 CHECK(last_handled_seq>=0));
CREATE TABLE input_queue(input_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),kind TEXT NOT NULL CHECK(kind IN ('ASK','STEER','CHANGE','CONTROL','REPLY')),target_role TEXT,state TEXT NOT NULL CHECK(state IN ('QUEUED','DELIVERED','APPLIED','REJECTED')),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
-- Indexes for every foreign key used in hot paths and for scheduler/dispatcher scans.
CREATE INDEX events_project_seq ON events(project_id,seq);
CREATE INDEX events_run_kind ON events(run_id,kind,seq);
CREATE INDEX change_requests_project ON change_requests(project_id,state);
CREATE INDEX runs_project_state ON runs(project_id,state);
CREATE INDEX tasks_run_state ON tasks(run_id,state,created_seq);
CREATE INDEX tasks_retry ON tasks(next_retry_at) WHERE next_retry_at IS NOT NULL;
CREATE INDEX task_dependencies_reverse ON task_dependencies(depends_on);
CREATE INDEX task_requirements_requirement ON task_requirements(requirement_id,spec_id);
CREATE INDEX attempts_task ON attempts(task_id,state);
CREATE INDEX attempts_session ON attempts(session_id);
CREATE INDEX leases_attempt ON leases(attempt_id);
CREATE INDEX candidates_run ON candidates(run_id,created_at);
CREATE INDEX evidence_candidate ON evidence(candidate_id,check_id);
CREATE INDEX evidence_attempt ON evidence(attempt_id);
CREATE INDEX evidence_artifact ON evidence(artifact_id);
CREATE INDEX acceptance_results_candidate ON acceptance_results(candidate_id,status);
CREATE INDEX acceptance_results_evidence ON acceptance_results(evidence_id);
CREATE INDEX issues_run_state ON issues(run_id,state,severity);
CREATE INDEX releases_run ON releases(run_id);
CREATE INDEX commands_run ON commands(run_id);
CREATE INDEX outbox_dispatch ON outbox(state,next_retry_at);
CREATE INDEX outbox_event ON outbox(event_seq);
CREATE INDEX receipts_message ON receipts(message_id);
CREATE INDEX handoffs_run ON handoffs(run_id,state);
CREATE INDEX effects_attempt ON effects(attempt_id,state);
CREATE INDEX decisions_run ON decisions(run_id,state);
CREATE INDEX supervisor_triggers_due ON supervisor_triggers(state,due_at);
CREATE INDEX supervisor_triggers_run ON supervisor_triggers(run_id,fingerprint);
CREATE UNIQUE INDEX supervisor_triggers_pending_key ON supervisor_triggers(run_id,fingerprint,ifnull(spec_id,'')) WHERE state='PENDING';
CREATE INDEX team_revisions_command ON team_revisions(command_id);
CREATE INDEX issues_report ON issues(report_id);
CREATE INDEX independent_reports_candidate ON independent_reports(candidate_id,role,state);
CREATE INDEX independent_reports_run ON independent_reports(run_id);
CREATE INDEX independent_reports_session ON independent_reports(session_id);
CREATE INDEX independent_reports_attempt ON independent_reports(attempt_id);
CREATE INDEX independent_reports_report_artifact ON independent_reports(report_artifact_id);
CREATE INDEX independent_reports_raw_artifact ON independent_reports(raw_session_artifact_id);
CREATE INDEX input_queue_run ON input_queue(run_id,state);
INSERT INTO schema_migrations VALUES(1,'2026-11-03T00:00:00Z');
PRAGMA user_version = 1;
COMMIT;
